type ExternalSystemWithT[T any] ExternalSystem

func (u *ExternalSystemWithT[T]) Accept(ctx context.Context, v ExternalSystemVisitorWithT[T]) (T, error) {
	var result T
	switch u.typ {
	default:
		if u.typ == "" {
			return result, fmt.Errorf("invalid value in union type")
		}
		return v.VisitUnknown(ctx, u.typ)
	case "palantirSystem":
		if u.palantirSystem == nil {
			return result, fmt.Errorf("field \"palantirSystem\" is required")
		}
		return v.VisitPalantirSystem(ctx, *u.palantirSystem)
	case "other":
		if u.other == nil {
			return result, fmt.Errorf("field \"other\" is required")
		}
		return v.VisitOther(ctx, *u.other)
	}
}

